  gap: 4px;
  align-items: center;
  max-width: 100%;
  padding: 0 6px;
  border-radius: var(--tmt-ui-radius-s);
  background: var(--tmt-ui-surface-selection);
  color: var(--tmt-ui-color-selected-text);
  font-size: 0.92em;
  text-decoration: none;
  vertical-align: baseline;
  white-space: nowrap;
}
.tmt-block-mention-text {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}
a.tmt-block-mention:hover {
  text-decoration: underline;
}
a.tmt-block-mention:focus-visible {
  outline: var(--tmt-ui-focus-width) solid var(--tmt-ui-color-focus);
}
.tmt-block-toast {
  display: inline-flex;
  gap: 12px;
  align-items: center;
  max-width: calc(100% - 32px);
  padding: 8px 8px 8px 14px;
  border-radius: var(--tmt-ui-radius);
  background: var(--tmt-ui-color-text);
  box-shadow: var(--tmt-ui-shadow-overlay);
  color: var(--tmt-ui-surface-sheet);
  font: 14px / 1.4 var(--tmt-ui-font-body);
}
.tmt-block-toast-message {
  min-width: 0;
  overflow-wrap: anywhere;
}
.tmt-block-toast-undo {
  padding: 2px 10px;
  border: var(--tmt-ui-rule-width) solid currentColor;
  border-radius: var(--tmt-ui-radius-s);
  background: none;
  color: inherit;
  font: inherit;
  font-weight: 600;
  cursor: pointer;
}
.tmt-block-toast-undo:focus-visible {
  outline: var(--tmt-ui-focus-width) solid var(--tmt-ui-color-focus);
  outline-offset: 2px;
}
.tmt-block-toast .tmt-block-kbd {
  border-color: currentColor;
  color: inherit;
}


@container tmt-block-doc (max-width: 480px) {
  .tmt-block-doc-body {
    --tmt-block-gutter: 8px;
  }
  .tmt-block-handle {
    display: none;
  }
  .tmt-block-todo {
    grid-template-columns: 20px minmax(0, 1fr);
  }
  .tmt-block-todo-meta {
    grid-column: 2;
    white-space: normal;
  }
  .tmt-block-card {
    padding: 12px;
  }
  .tmt-block-list {
    padding-inline-start: calc(var(--tmt-block-indent, 0) * 16px);
  }
}
@container tmt-block-table (max-width: 480px) {
  .tmt-block-table [data-hide-narrow] {
    display: none;
  }
}

.tmt-block-question {
  display: flex;
  gap: var(--tmt-ui-space-m);
  box-sizing: border-box;
  padding: var(--tmt-ui-space-m);
  border: var(--tmt-ui-rule-width) solid var(--tmt-ui-surface-rule);
  border-radius: var(--tmt-ui-radius);
  background: var(--tmt-ui-surface-sheet);
  color: var(--tmt-ui-color-text);
  font: var(--tmt-ui-type-body-size)/var(--tmt-ui-type-body-line-height) var(--tmt-ui-font-body);
}
.tmt-block-question-mark {
  display: grid;
  place-items: center;
  width: 22px;
  height: 22px;
  border-radius: var(--tmt-ui-radius-pill);
  background: var(--tmt-ui-surface-hover);
  color: var(--tmt-ui-color-text);
  flex: none;
}
.tmt-block-question-content {
  min-width: 0;
  flex: 1;
}
.tmt-block-question-eyebrow {
  color: var(--tmt-ui-color-secondary);
  font-size: var(--tmt-ui-caption-size);
}
.tmt-block-question h3 {
  margin: 0 0 var(--tmt-ui-space-s);
}
.tmt-block-question fieldset {
  border: 0;
  margin: 0;
  padding: 0;
}
.tmt-block-question legend {
  color: var(--tmt-ui-color-secondary);
  font-size: var(--tmt-ui-caption-size);
}
.tmt-block-question-choices {
  display: flex;
  flex-wrap: wrap;
  gap: var(--tmt-ui-space-xs);
}
.tmt-block-question-choices label {
  display: flex;
  align-items: center;
  gap: var(--tmt-ui-space-xs);
  border: var(--tmt-ui-rule-width) solid var(--tmt-ui-color-edge);
  border-radius: var(--tmt-ui-radius);
  padding: var(--tmt-ui-space-xs) var(--tmt-ui-space-s);
}
.tmt-block-question-choices kbd {
  color: var(--tmt-ui-color-secondary);
