    flex-direction: column;
  }
}
.tmt-block-images {
  display: flex;
  flex-direction: column;
  gap: var(--tmt-ui-space-s);
  min-width: 0;
}
.tmt-block-image-list {
  display: flex;
  gap: var(--tmt-ui-space-s);
  overflow-x: auto;
  min-width: 0;
}
.tmt-block-images[data-layout='carousel'] .tmt-block-image-list {
  scroll-snap-type: x proximity;
}
.tmt-block-images[data-layout='carousel'] figure {
  scroll-snap-align: start;
}

.tmt-block-images[data-layout='grid'] .tmt-block-image-list {
  --tmt-block-tile: 140px;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(var(--tmt-block-tile), 1fr));
}
.tmt-block-images[data-layout='grid'][data-size='m'] .tmt-block-image-list {
  --tmt-block-tile: 200px;
}
.tmt-block-images[data-layout='grid'][data-size='l'] .tmt-block-image-list {
  --tmt-block-tile: 280px;
}

.tmt-block-images figcaption {
  word-break: keep-all;
  overflow-wrap: break-word;
}
.tmt-block-images figure {
  flex: none;
  margin: 0;
}
.tmt-block-images figure button {
  border: 0;
  padding: 0;
  background: transparent;
  cursor: pointer;
}
.tmt-block-images figure img,
.tmt-block-image-placeholder {
  display: block;
  height: 180px;
  max-width: 100%;
  object-fit: contain;
}
.tmt-block-images[data-size='s'] figure img,
.tmt-block-images[data-size='s'] .tmt-block-image-placeholder {
  height: 140px;
}
.tmt-block-images[data-size='l'] figure img,
.tmt-block-images[data-size='l'] .tmt-block-image-placeholder {
  height: 240px;
}
.tmt-block-image-placeholder {
  width: 180px;
  background: var(--tmt-ui-surface-hover);
}
.tmt-block-image-controls,
.tmt-block-image-viewer-controls,
.tmt-block-file {
  display: flex;
  align-items: center;
  gap: var(--tmt-ui-space-s);
}
.tmt-block-file {
  border: var(--tmt-ui-rule-width) solid var(--tmt-ui-color-edge);
  padding: var(--tmt-ui-space-s);
}
.tmt-block-file svg {
  width: 16px;
  height: 16px;
  flex: none;
}
.tmt-block-file span:first-of-type {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.tmt-block-image-viewer-canvas {
  display: grid;
  place-items: center;
  overflow: auto;
  min-height: 0;
  touch-action: none;
}
.tmt-block-image-viewer-canvas img {
  max-width: 100%;
  max-height: 70vh;
  object-fit: contain;
}
@media (max-width: 760px) {
  .tmt-block-images figure img,
  .tmt-block-image-placeholder {
    height: 120px;
  }
  .tmt-block-images[data-size='s'] figure img,
  .tmt-block-images[data-size='s'] .tmt-block-image-placeholder {
    height: 96px;
  }
  .tmt-block-images[data-size='l'] figure img,
  .tmt-block-images[data-size='l'] .tmt-block-image-placeholder {
    height: 160px;
  }
  .tmt-block-image-controls button {
    display: none;
  }
}

.tmt-block-work {
  border: var(--tmt-ui-rule-width) solid var(--tmt-ui-color-edge);
  border-radius: var(--tmt-ui-radius);
  padding: var(--tmt-ui-space-m);
  color: var(--tmt-ui-color-text);
  font: var(--tmt-ui-type-body-size)/var(--tmt-ui-type-body-line-height) var(--tmt-ui-font-body);
}
.tmt-block-work header {
  display: flex;
  gap: var(--tmt-ui-space-s);
  align-items: start;
}
.tmt-block-work-number {
  border-radius: var(--tmt-ui-radius);
  padding: 0 var(--tmt-ui-space-xs);
  background: var(--tmt-ui-surface-hover);
}
.tmt-block-work-meta,
.tmt-block-work-tickets {
  display: flex;
  flex-wrap: wrap;
  gap: var(--tmt-ui-space-xs);
}
.tmt-block-work-meta {
  color: var(--tmt-ui-color-secondary);
  font-size: var(--tmt-ui-caption-size);
}
.tmt-block-work-field {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: var(--tmt-ui-space-s);
}
.tmt-block-work-field textarea {
  width: 100%;
}
@media (max-width: 760px) {
  .tmt-block-work-field {
    grid-template-columns: 1fr;
  }
}
.tmt-block-mockup-toolbar {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: var(--tmt-ui-space-xs) var(--tmt-ui-space-s);
}

.tmt-block-mockup-pin {
  min-width: 0;
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  padding: 0 var(--tmt-ui-space-s);
  border-radius: var(--tmt-ui-radius-pill);
  background: var(--tmt-ui-surface-hover);
  color: var(--tmt-ui-color-secondary);
  font: var(--tmt-ui-caption-size) / var(--tmt-ui-caption-line-height) var(--tmt-ui-font-mono);
}

.tmt-block-mockup-segments {
  display: inline-flex;
  flex-wrap: nowrap;
}
.tmt-block-mockup-segments > button {
  min-height: var(--tmt-ui-control-size);
  margin: 0;
  padding: 0 var(--tmt-ui-space-s);
  border: var(--tmt-ui-rule-width) solid var(--tmt-ui-surface-rule);
  border-radius: 0;
  background: var(--tmt-ui-surface-sheet);
  color: var(--tmt-ui-color-secondary);
  font: inherit;
  white-space: nowrap;
  cursor: pointer;
}
.tmt-block-mockup-segments > button + button {
  margin-inline-start: calc(-1 * var(--tmt-ui-rule-width));
}
.tmt-block-mockup-segments > button:first-child {
  border-start-start-radius: var(--tmt-ui-radius);
  border-end-start-radius: var(--tmt-ui-radius);
}
.tmt-block-mockup-segments > button:last-child {
  border-start-end-radius: var(--tmt-ui-radius);
  border-end-end-radius: var(--tmt-ui-radius);
}
.tmt-block-mockup-segments > button[aria-pressed='true'] {
  position: relative;
  z-index: 1;
  border-color: var(--tmt-ui-color-edge);
  background: var(--tmt-ui-surface-selection);
  color: var(--tmt-ui-color-selected-text);
  font-weight: 500;
}
.tmt-block-mockup-segments > button:focus-visible {
  position: relative;
  z-index: 1;
  outline: var(--tmt-ui-focus-width) solid var(--tmt-ui-color-focus);
}

.tmt-block-mockup-viewport {
  overflow: clip;
  background: var(--tmt-ui-surface-hover);
}

.tmt-block-mockup-stage {
  margin-inline: auto;
  transform-origin: top left;
  background: var(--tmt-ui-surface-paper);
}
.tmt-block-mockup-scale {
  color: var(--tmt-ui-color-secondary);
  font-size: var(--tmt-ui-caption-size);
}
.tmt-block-images[data-layout='grid'] figure img {
  aspect-ratio: 4/3;
  width: 100%;
  height: auto;
  object-fit: cover;
}
@container tmt-ds-scope (max-width:760px) {
  .tmt-block-question-choices {
    flex-direction: column;
  }
  .tmt-block-images figure img,
  .tmt-block-image-placeholder {
    height: 120px;
  }
  .tmt-block-images[data-size='s'] figure img,
  .tmt-block-images[data-size='s'] .tmt-block-image-placeholder {
    height: 96px;
  }
  .tmt-block-images[data-size='l'] figure img,
  .tmt-block-images[data-size='l'] .tmt-block-image-placeholder {
    height: 160px;
  }
  .tmt-block-images[data-layout='grid'] figure img {
    height: auto;
  }
  .tmt-block-image-controls button {
    display: none;
  }
  .tmt-block-work-field {
    grid-template-columns: 1fr;
  }
  .tmt-block-image-viewer[data-slot='dialog-content'] {
    inset: 0;
    width: 100cqw;
    height: 100cqh;
    max-width: none;
    max-height: none;
    transform: none;
    translate: none;
  }
}
@media (max-width: 760px) {
  .tmt-block-images[data-layout='grid'] figure img {
    height: auto;
  }
  .tmt-block-image-viewer[data-slot='dialog-content'] {
    inset: 0;
    width: 100%;
    height: 100%;
    max-width: none;
    max-height: none;
    transform: none;
    translate: none;
  }
}

.tmt-block-mockup-host,
.tmt-block-mockup {
  width: 100%;
  min-width: 0;
}
.tmt-block-mockup-toolbar {
  min-width: 0;
}
.tmt-block-mockup-toolbar input {
  max-width: 6em;
}
.tmt-block-work header > div {
  min-width: 0;
}
.tmt-block-work header a {
  overflow-wrap: anywhere;
}
.tmt-block-page-toolbar-host {
  width: 100%;
  min-width: 0;
}
.tmt-block-page-toolbar {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: var(--tmt-ui-space-s);
}
.tmt-block-page-toolbar select {
  font: inherit;
  color: inherit;
  background: var(--tmt-ui-surface-paper);
  border: var(--tmt-ui-rule-width) solid var(--tmt-ui-color-edge);
  border-radius: var(--tmt-ui-radius);
}
.tmt-block-page-filter {
  display: inline-flex;
  align-items: center;
  gap: var(--tmt-ui-space-xs);
  border-radius: var(--tmt-ui-radius);
  background: var(--tmt-ui-surface-hover);
  padding: var(--tmt-ui-space-xs);
}
.tmt-block-page-filter button {
  border: 0;
  background: transparent;
  color: inherit;
  cursor: pointer;
}
.tmt-block-page-columns {
  display: grid;
  gap: var(--tmt-ui-space-m);
}
.tmt-block-page-columns label {
  display: flex;
  align-items: center;
  gap: var(--tmt-ui-space-s);
}

.tmt-block-work-host {
  width: 100%;
  min-width: 0;
}
.tmt-block-work header a {
  color: inherit;
  font-weight: 600;
  text-decoration: none;
}
.tmt-block-work header a:hover {
  text-decoration: underline;
}
.tmt-block-work-attention {
  color: var(--tmt-ui-color-waiting);
}

}



@scope (.tmt-design-docs) {

:scope {
  color-scheme: dark;
}
:scope[data-theme='light'] {
  color-scheme: light;
}
:scope {
  margin: 0;
  background: var(--tmt-ui-surface-paper);
  color: var(--tmt-ui-color-text);
  font: var(--tmt-ui-ref-size-4) / 1.6 var(--tmt-ui-font-body);
  -webkit-font-smoothing: antialiased;
}
a {
  color: inherit;
}
code {
  font: 0.9em var(--tmt-ui-font-mono);
}


.docs-top {
  position: sticky;
  top: 0;
  z-index: 10;
  display: flex;
  align-items: center;
  gap: var(--tmt-ui-ref-space-5);
  height: 56px;
  padding: 0 var(--tmt-ui-ref-space-5);
  border-bottom: var(--tmt-ui-rule-width) solid var(--tmt-ui-surface-rule);
  background: var(--tmt-ui-surface-paper);
}
.docs-brand {
  display: flex;
  align-items: center;
  gap: var(--tmt-ui-ref-space-2);
  font-weight: 700;
  font-size: var(--tmt-ui-ref-size-5);
  text-decoration: none;
}
.docs-brand-sub {
  color: var(--tmt-ui-color-secondary);
  font-weight: 400;
}
.docs-segment {
  display: flex;
  border: var(--tmt-ui-rule-width) solid var(--tmt-ui-surface-rule);
  border-radius: var(--tmt-ui-radius);
  overflow: hidden;
}
.docs-segment > :is(button, a),
.docs-menu-button {
  padding: var(--tmt-ui-ref-space-1) var(--tmt-ui-ref-space-4);
  border: 0;
  background: transparent;
  color: var(--tmt-ui-color-secondary);
  font: var(--tmt-ui-ref-size-2) var(--tmt-ui-font-body);
  cursor: pointer;
}
.docs-segment > :is(button, a) + :is(button, a) {
  border-left: var(--tmt-ui-rule-width) solid var(--tmt-ui-surface-rule);
}

.docs-systems > a {
  text-decoration: none;
  white-space: nowrap;
}
.docs-segment > :is(button[aria-pressed='true'], a[aria-current='page']) {
  background: var(--tmt-ui-surface-selection);
  color: var(--tmt-ui-color-text);
}
.docs-menu-button {
  display: none;
  font-size: var(--tmt-ui-ref-size-6);
}
:is(.docs-segment > button, .docs-segment > a, .docs-menu-button):focus-visible {
  outline: var(--tmt-ui-focus-width) solid var(--tmt-ui-color-focus);
}


.docs {
  --docs-top: 56px;
  --docs-viewport: 100dvh;
}
.docs-body {
  display: grid;
  grid-template-columns: 240px minmax(0, 1fr);
  max-width: 1280px;
  margin: 0 auto;
}
.docs-nav {
  position: sticky;
  top: var(--docs-top);
  align-self: start;
  height: calc(var(--docs-viewport) - var(--docs-top));
  overflow-y: auto;
  overscroll-behavior: contain;
  padding: var(--tmt-ui-ref-space-6) var(--tmt-ui-ref-space-4);
  box-sizing: border-box;
}
.docs-nav-group {
  display: grid;
  gap: 1px;
  margin-bottom: var(--tmt-ui-ref-space-5);
}
.docs-nav-title {
  margin: 0 0 var(--tmt-ui-ref-space-1);
  padding: 0 var(--tmt-ui-ref-space-2);
  font-size: var(--tmt-ui-ref-size-3);
  font-weight: 600;
}
.docs-nav a {
  padding: var(--tmt-ui-ref-space-1) var(--tmt-ui-ref-space-2);
  border-radius: var(--tmt-ui-radius);
  color: var(--tmt-ui-color-secondary);
  font-size: var(--tmt-ui-ref-size-3);
  text-decoration: none;
}
.docs-nav a:hover {
  color: var(--tmt-ui-color-text);
}
.docs-nav a[aria-current='page'] {
  background: var(--tmt-ui-surface-selection);
  color: var(--tmt-ui-color-text);
  font-weight: 600;
}
.docs-main {
  min-width: 0;
  padding: var(--tmt-ui-ref-space-6) var(--tmt-ui-ref-space-5) 96px;
}
.docs-article {
  max-width: 760px;
}
.docs-article h1 {
  margin: 0 0 var(--tmt-ui-ref-space-2);
  font-size: var(--tmt-ui-ref-size-8);
  font-weight: 700;
  letter-spacing: -0.02em;
  line-height: 1.2;
}
.docs-lead {
  margin: 0 0 var(--tmt-ui-ref-space-6);
  color: var(--tmt-ui-color-secondary);
  font-size: var(--tmt-ui-ref-size-5);
}
.docs-article h2 {
  margin: 48px 0 var(--tmt-ui-ref-space-3);
  padding-bottom: var(--tmt-ui-ref-space-2);
  border-bottom: var(--tmt-ui-rule-width) solid var(--tmt-ui-surface-rule);
  font-size: var(--tmt-ui-ref-size-7);
  font-weight: 650;
  letter-spacing: -0.01em;
}
.docs-article h3 {
  margin: var(--tmt-ui-ref-space-5) 0 var(--tmt-ui-ref-space-2);
  font-size: var(--tmt-ui-ref-size-4);
  font-weight: 600;
}

.docs-article h2,
.docs-article h3 {
  line-height: 1.6;
}
.docs-article pre code {
  font: 0.9em var(--tmt-ui-font-mono);
}

.docs-article {
  overflow-wrap: normal;
